DELIMITER $$
CREATE TRIGGER `comentarios_after_insert` AFTER INSERT ON `comentarios` FOR EACH ROW BEGIN
	DECLARE ciudad_id INTEGER;
	DECLARE total_by_city INTEGER;
	DECLARE total_comentarios_ciudad INTEGER;
	DECLARE total_porcentage_final FLOAT;
	DECLARE codigo_departamento_ciudad VARCHAR (50);
	DECLARE id_departamento INTEGER;
	DECLARE id_vereda INTEGER;
	DECLARE total_ciudades FLOAT;
	DECLARE total_vereda INTEGER;
	DECLARE final_vereda FLOAT;
	DECLARE total_comentarios_vereda INTEGER;
	
	SET ciudad_id = NEW.municipio_id;
	SET id_vereda = NEW.vereda_id;
	SET total_by_city = (SELECT total FROM tbl_ciudades WHERE id = ciudad_id );
	SET total_vereda = (SELECT total FROM tbl_vereda WHERE id = id_vereda );
	SET codigo_departamento_ciudad = (SELECT codigo_departamento FROM tbl_ciudades WHERE id = ciudad_id );
	SET id_departamento = (SELECT id FROM tbl_departamentos WHERE codigo_departamento = codigo_departamento_ciudad );
	SET total_comentarios_ciudad = ( SELECT COUNT(id) FROM comentarios WHERE municipio_id = ciudad_id );
	SET total_comentarios_vereda = ( SELECT COUNT(id) FROM comentarios WHERE vereda_id = id_vereda );
	
	IF (total_by_city IS NULL OR total_by_city = 0 ) THEN
		set total_by_city = 1;
	END IF;
	
	IF (total_vereda IS NULL OR total_vereda = 0 ) THEN
		set total_vereda = 1;
	END IF;
	
	SET total_porcentage_final = total_comentarios_ciudad / total_by_city * 100;
	
	SET final_vereda = total_comentarios_vereda / total_vereda * 100;
	
	UPDATE tbl_ciudades SET porcentaje_participacion = total_porcentage_final WHERE id = ciudad_id;
	
	SET total_ciudades = ( SELECT SUM(porcentaje_participacion) FROM tbl_ciudades WHERE codigo_departamento = codigo_departamento_ciudad );
	
	UPDATE tbl_departamentos SET total_porcentaje = total_ciudades WHERE codigo_departamento = codigo_departamento_ciudad;
	UPDATE tbl_colombia SET total_porcentaje = total_ciudades WHERE tbl_departamento_id = id_departamento;
	UPDATE tbl_vereda SET porcentaje_participacion = final_vereda WHERE id = id_vereda;
END
$$
DELIMITER ;

