INSERT INTO `tbl_compromisos` (`id`, `provincia`, `compromisos`, `tbl_departamento_id`, `tbl_municipio_id`, `cumplimiento`, `tbl_secretarias_id`, `img`, `tbl_usuario_id`, `respuesta`, `created_at`, `date`) VALUES
(1, '', 'Se requiere conectividad para la instituciones educativas, los punto de acceso de internet para la ciudadanía. Equipos de cómputo para la diferentes sedes educativas. Capacitaciones en las nuevas políticas de tecnologías.', 68, 68051, 'Sin Cumplir', '10', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-12'),
(2, '', 'Realizar un convenio para la siembra de árboles, fijando una meta para cada una, donde la CDMB y la CAS colocan el material vegetal y el Ejército Nacional las planta.', 68, 68079, 'Sin Cumplir', '29', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-12'),
(3, '', 'Solicitar a la CAS no reducir el caudal de la concesión y agilizar los permisos para perforación de pozos profundos y concesión del agua.', 68, 68079, 'Sin Cumplir', '29', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-12'),
(4, '', 'Aprobación del comodato para el colegio Técnico Aquileo Parra:', 68, 68079, 'Sin Cumplir', '7', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-21'),
(5, '', 'Avances para la solución del problema de desabastecimiento de Agua.', 68, 68079, 'Sin Cumplir', '23', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-04'),
(6, '', 'Solicitud a los alcaldes a que revisen las pérdidas de agua que tiene cada uno de los acueductos Barichara el 51% y Villanueva 75%, recordando que el maximo por norma es el 25%.', 68, 68079, 'Sin Cumplir', '23', '', 2, NULL, '0000-00-00 00:00:00', '2024-01-04'),
