INSERT INTO `tbl_plandesarrollo` (`id`, `eje_estrategico`, `sector_pdd`, `sector_cat_prod`, `producto_servicio_pdd`, `tbl_secretaria_id`, `direccion_resp`, `ps2024`, `avance_2024`, `avance_2025`, `ps2025`, `ps2026`, `ps2027`, `user_id`, `dtcreate`, `dtupdate`) VALUES
(1, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de fomento para el acceso a la educación inicial, preescolar, básica y media, organizando la oferta educativa para las instituciones oficiales de los municipios no certificados del departamento de Santander, con estrategias que beneficie a la población estudiantil con enfoque diferencial (discapacidad, víctimas, comunidades indígenas, jóvenes del sistema de responsabilidad penal adolescente, población vulnerable)', 7, 'Grupo Cobertura educativa', '11126', '', NULL, '11126', '11126', '11126', 0, '0000-00-00 00:00:00', NULL),
(2, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de apoyo a la permanencia con alimentación escolar PAE que aporten a la seguridad alimentaria de los niños, niñas, adolescentes y jóvenes – NNAJ matriculados en las instituciones educativas rurales y no rurales de los municipios no certificados del Departamento de Santander, caracterizados en el SIMAT.', 7, 'Dirección de Permanencia Escolar', '135000', '', NULL, '135000', '135000', '135000', 0, '0000-00-00 00:00:00', NULL),
(3, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de apoyo a la permanencia con transporte escolar para fortalecer las acciones de retención estudiantil de los niños, niñas, adolescentes y jóvenes caracterizados en el SIMAT.', 7, 'Dirección de Permanencia Escolar', '27000', '', NULL, '27000', '27000', '27000', 0, '0000-00-00 00:00:00', NULL),
(4, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio educativo de promoción del bilingüismo para mejorar las competencias en un segundo idioma a docentes y estudiantes de los establecimientos educativos no certificados del Departamento de Santander.', 7, 'grupo calidad educativa', '60', '', NULL, '60', '60', '60', 0, '0000-00-00 00:00:00', NULL),
(5, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Documentos de lineamientos técnicos para diseñar e implementar el Plan de articulación de la media con la educación superior en los 82 municipios no certificados del Departamento de Santander.', 7, 'grupo calidad educativa', '1', '', NULL, 'NP', '7', 'NP', 0, '0000-00-00 00:00:00', NULL),
(6, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de orientación socio ocupacional para la toma de decisiones sobre su educación y formación posmedia, para la vida laboral de los estudiantes de los grados 9, 10 y 11 de los establecimientos educativos no certificados del Departamento de Santander, en el marco del plan de articulación de la educación media y la educación superior.', 7, 'grupo calidad educativa', '12500', '', NULL, '12500', '12500', '12500', 0, '0000-00-00 00:00:00', NULL),
(7, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicios de asistencia técnica en innovación educativa en la educación inicial, preescolar, básica y media, para mejorar las competencias y habilidades en lenguaje y escritura en los establecimientos educativos rurales y no rurales de los municipios no certificados del Departamento de Santander.', 7, 'grupo calidad educativa', '5', '', NULL, '10', '10', '5', 0, '0000-00-00 00:00:00', NULL),
(8, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de fortalecimiento a las capacidades de los docentes de educación Inicial, preescolar, básica y media de los establecimientos educativos no certificados del Departamento de Santander, mediante programas de formación con la academia y otros sectores, en el marco del plan territorial de formación docente.', 7, 'grupo calidad educativa', '200', '', NULL, '600', '600', '600', 0, '0000-00-00 00:00:00', NULL),
(9, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de atención integral para la primera infancia, con el fin de fortalecer el ciclo II de la educación inicial (pre jardín, jardín y transición) de los municipios no certificados de Santander.', 7, 'grupo calidad educativa', '5', '', NULL, '9', '9', '9', 0, '0000-00-00 00:00:00', NULL),
(10, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de asistencia técnica en educación inicial, preescolar, básica y media, para orientar y fortalecer el desarrollo de las estrategias de calidad educativa en los establecimientos educativos, incluidos los viabilizados para la estrategia de ampliación y uso significativo del tiempo escolar, de los 82 municipios no certificados de Santander', 7, 'grupo calidad educativa', '273', '', NULL, '273', '273', '273', 0, '0000-00-00 00:00:00', NULL),
(11, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Infraestructura educativa construida, desde la puesta en marcha para fortalecer el acceso y permanencia de los estudiantes de las instituciones educativas dentro de los 82 municipios no certificados del Departamento.', 7, 'Dirección Administrativa y Financiera', '1', '', NULL, '2', '1', '0', 0, '0000-00-00 00:00:00', NULL),
(12, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Infraestructura educativa mejorada, para fortalecer el acceso y permanencia de los estudiantes de las instituciones educativas de los 82 municipios no certificados del Departamento.', 7, 'Dirección Administrativa y Financiera', '10', '', NULL, '50', '40', '20', 0, '0000-00-00 00:00:00', NULL),
(13, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Infraestructura educativa dotada para fortalecer el acceso y permanencia de los estudiantes de las instituciones educativas de los 82 municipios no certificados del Departamento.', 7, 'Dirección Administrativa y Financiera', '20', '', NULL, '80', '80', '20', 0, '0000-00-00 00:00:00', NULL),
(14, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio educativo para fortalecer la prestación del servicio en los 82 municipios no certificados del Departamento de Santander', 7, 'Dirección Administrativa y Financiera', '273', '', NULL, '273', '273', '273', 0, '0000-00-00 00:00:00', NULL),
(15, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicio de accesibilidad a contenidos web para fines pedagógicos en los establecimientos educativos rurales y no rurales de los municipios no certificados del Departamento de Santander.', 7, 'Dirección Administrativa y Financiera', '50', '', NULL, '100', '100', '23', 0, '0000-00-00 00:00:00', NULL),
(16, 'EJE SEGURIDAD MULTIDIMENSIONAL ', 'ES TIEMPO DE LA EDUCACIÓN', 'EDUCACIÓN ', 'Servicios conexos a la prestación del servicio educativo oficial, para los docentes de los establecimientos educativos no certificados del Departamento de Santander, brindados a través del Plan de Bienestar Docente y fortalecimiento de los sistemas de información.', 7, 'Direccion de Talento Humano', '7921', '', NULL, '7921', '7921', '7921', 0, '0000-00-00 00:00:00', NULL),
